CREATE TABLE companies (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(180) NOT NULL, contact_person VARCHAR(160), email VARCHAR(255) NOT NULL UNIQUE, phone VARCHAR(40), password_hash VARCHAR(100) NOT NULL, industry_type VARCHAR(40) NOT NULL, role VARCHAR(20) NOT NULL, state VARCHAR(100), city VARCHAR(100), address VARCHAR(500), lat DOUBLE PRECISION, lng DOUBLE PRECISION, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE materials (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(160) NOT NULL UNIQUE, category VARCHAR(100), default_unit VARCHAR(30) DEFAULT 'tonne', emission_factor_kg_per_tonne DOUBLE PRECISION DEFAULT 0, factor_source VARCHAR(255), factor_note VARCHAR(255));
CREATE TABLE company_residues (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_id BIGINT NOT NULL REFERENCES companies(id) ON DELETE CASCADE, material_id BIGINT REFERENCES materials(id), custom_name VARCHAR(160), qty_per_month_tonnes DOUBLE PRECISION NOT NULL, disposal_method VARCHAR(40), disposal_cost_per_tonne DOUBLE PRECISION);
CREATE TABLE company_needs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_id BIGINT NOT NULL REFERENCES companies(id) ON DELETE CASCADE, material_id BIGINT NOT NULL REFERENCES materials(id), qty_per_month_tonnes DOUBLE PRECISION NOT NULL, quality_notes VARCHAR(1000));
CREATE TABLE listings (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_id BIGINT NOT NULL REFERENCES companies(id), material_id BIGINT NOT NULL REFERENCES materials(id), title VARCHAR(200) NOT NULL, description VARCHAR(2000), quantity_tonnes DOUBLE PRECISION NOT NULL, price_per_tonne DOUBLE PRECISION NOT NULL, moisture_pct DOUBLE PRECISION, purity_pct DOUBLE PRECISION, grade VARCHAR(100), composition_notes VARCHAR(1000), available_from DATE, status VARCHAR(20) DEFAULT 'ACTIVE', certificate_url VARCHAR(500), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE requirements (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, buyer_id BIGINT NOT NULL REFERENCES companies(id) ON DELETE CASCADE, material_id BIGINT NOT NULL REFERENCES materials(id), min_qty_tonnes DOUBLE PRECISION NOT NULL, max_qty_tonnes DOUBLE PRECISION NOT NULL, max_price_per_tonne DOUBLE PRECISION NOT NULL, max_moisture_pct DOUBLE PRECISION, min_purity_pct DOUBLE PRECISION, preferred_radius_km DOUBLE PRECISION, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE compatibility_rules (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, material_id BIGINT NOT NULL REFERENCES materials(id) ON DELETE CASCADE, accepted_industry_type VARCHAR(40) NOT NULL, max_moisture_pct DOUBLE PRECISION, min_purity_pct DOUBLE PRECISION, notes VARCHAR(500));
CREATE TABLE exchange_requests (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, listing_id BIGINT NOT NULL REFERENCES listings(id), buyer_id BIGINT NOT NULL REFERENCES companies(id), requested_qty_tonnes DOUBLE PRECISION NOT NULL, offered_price_per_tonne DOUBLE PRECISION NOT NULL, message VARCHAR(1000), status VARCHAR(20) DEFAULT 'PENDING', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, distance_km DOUBLE PRECISION, transport_cost_inr DOUBLE PRECISION, revenue_inr DOUBLE PRECISION, avoided_disposal_inr DOUBLE PRECISION, net_benefit_inr DOUBLE PRECISION, waste_diverted_tonnes DOUBLE PRECISION, co2_avoided_kg DOUBLE PRECISION);
CREATE TABLE ratings (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, exchange_id BIGINT NOT NULL REFERENCES exchange_requests(id) ON DELETE CASCADE, rater_id BIGINT NOT NULL REFERENCES companies(id), rated_company_id BIGINT NOT NULL REFERENCES companies(id), score INT NOT NULL CHECK(score BETWEEN 1 AND 5), comment VARCHAR(1000), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(exchange_id,rater_id));
CREATE TABLE app_config (id INT PRIMARY KEY, transport_rate_inr_per_tonne_km DOUBLE PRECISION NOT NULL, transport_emission_kg_per_tonne_km DOUBLE PRECISION NOT NULL);
CREATE TABLE login_attempts (email VARCHAR(255) PRIMARY KEY, failed_count INT NOT NULL DEFAULT 0, locked_until TIMESTAMP);
